from math import sqrt, exp
vectors=[(1/sqrt(3),)*3,(1/sqrt(2),-1/sqrt(2),0),(1/sqrt(6),1/sqrt(6),-2/sqrt(6))]
data=[(tuple(sign*t for t in x),y) for x,y in zip(vectors,[1,1,5]) for sign in [-1,1]]
def dot(a,b): return sum(x*y for x,y in zip(a,b))
def risk(lam,aug=False):
 return sum(1.5*(exp(dot(lam, x[k:]+x[:k]))-y)**2 for x,y in data for k in (range(3) if aug else [0]))/(len(data)*(3 if aug else 1))
def hess(v,w,aug=False):
 return sum(3*(2-y)*dot(v,x[k:]+x[:k])*dot(w,x[k:]+x[:k]) for x,y in data for k in (range(3) if aug else [0]))/(len(data)*(3 if aug else 1))
for mode in [False,True]:
 print('Augmented' if mode else 'Nominal')
 print('Hessian in basis a,b,c:',[[round(hess(v,w,mode),8) for w in vectors] for v in vectors])
 print('Risk at zero:',risk((0,0,0),mode))
 for i,v in enumerate(vectors[:2]):
  step=tuple(0.01*t for t in v)
  print('Risk change along admissible basis',i,':',risk(step,mode)-risk((0,0,0),mode))
